-- MySQL Employee Practice Dataset
-- 1,000 dummy employee records
-- Designed for practicing SELECT, WHERE, GROUP BY, HAVING, ORDER BY,
-- aggregate functions, string/date functions, CASE, joins, subqueries, etc.

DROP TABLE IF EXISTS employees;

CREATE TABLE employees (
    id INT PRIMARY KEY,
    first_name VARCHAR(50) NOT NULL,
    last_name VARCHAR(50) NOT NULL,
    email VARCHAR(150) UNIQUE NOT NULL,
    age INT,
    department VARCHAR(50),
    job_title VARCHAR(80),
    salary DECIMAL(10,2),
    city VARCHAR(50),
    hire_date DATE,
    status VARCHAR(20)
);

